changeSet.sql:
INSERT INTO catalog_harvest_status_migration_backup ( entity_type, entity_id, previous_lifecycle_status ) SELECT 'CATALOG_DATASET', id, lifecycle_status FROM catalog_dataset WHERE upper(lifecycle_status) IN ('SYNCED', 'STALE');
INSERT INTO catalog_harvest_status_migration_backup ( entity_type, entity_id, previous_lifecycle_status ) SELECT 'CATALOG_ASSET_EXTENSION', id, lifecycle_status FROM catalog_asset_extension WHERE upper(lifecycle_status) IN ('SYNCED', 'STALE');
UPDATE catalog_dataset SET harvest_status = upper(lifecycle_status), lifecycle_status = 'PENDING_GOVERNANCE' WHERE upper(lifecycle_status) IN ('SYNCED', 'STALE');
UPDATE catalog_asset_extension SET lifecycle_status = 'PENDING_GOVERNANCE' WHERE upper(lifecycle_status) IN ('SYNCED', 'STALE');
